public class QueryBuilderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("selectAll two columns",
                  "SELECT id, name FROM users",
                  QueryBuilder.selectAll("users", new String[] {"id", "name"}));
            check("selectAll one column",
                  "SELECT msg FROM logs",
                  QueryBuilder.selectAll("logs", new String[] {"msg"}));
            check("selectAll three columns",
                  "SELECT id, name, email FROM people",
                  QueryBuilder.selectAll("people", new String[] {"id", "name", "email"}));
            check("selectAll no columns uses *",
                  "SELECT * FROM users",
                  QueryBuilder.selectAll("users", new String[] {}));
            check("selectWhere single column",
                  "SELECT name FROM users WHERE id = ?",
                  QueryBuilder.selectWhere("users", new String[] {"name"}, "id"));
            check("selectWhere two columns",
                  "SELECT id, total FROM orders WHERE customer_id = ?",
                  QueryBuilder.selectWhere("orders", new String[] {"id", "total"}, "customer_id"));
            check("selectWhere no columns",
                  "SELECT * FROM orders WHERE id = ?",
                  QueryBuilder.selectWhere("orders", new String[] {}, "id"));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected a normal return but got " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

